import 'package:flutter_test/flutter_test.dart';
import 'package:logger/logger.dart';
import 'package:zephyr/util/error_filter.dart';

void main() {
  test('sanitize dataURL error', () {
    final e =
        'AnyhowException(fetch failed: builder error for url (data:image/png;base64,))';
    final out = sanitizeErrorText(e);
    // ignore: avoid_print
    print('LEN-IN=${e.length} LEN-OUT=${out.length} OUT=$out');
    expect(out.contains('iVBORw0'), isFalse);
    expect(out.contains('<base64('), isTrue);
  });

  test('printer log sanitizes error section', () {
    // 单行超阈值（>2000）才清洗：用 3000 字符 base64 模拟真实 dataURL 行。
    final longB64 = 'iVBORw0KGgo${'QUJD' * 750}';
    final e = 'AnyhowException(x data:image/png;base64,$longB64)';
    final p = TersePrettyPrinter();
    final lines = p.log(
      LogEvent(
        Level.error,
        'msg',
        error: e,
        stackTrace: StackTrace.fromString('#0 foo\n#1 bar'),
      ),
    );
    final joined = lines.join('\n');
    for (var i = 0; i < lines.length; i++) {
      // ignore: avoid_print
      print('BOX[$i]: ${lines[i]}');
    }
    expect(joined.contains('iVBORw0'), isFalse);
    expect(joined.contains('<base64('), isTrue);
    // 堆栈换行保留：两帧不挤在一行（各占一个 │ 行）。
    final stackLines = joined
        .split('\n')
        .where((l) => l.contains('#0') || l.contains('#1'));
    expect(stackLines.length, 2);
    // 时间行保留：`HH:MM:SS.mmm (+H:MM:SS.micro)` 格式。
    expect(
      joined
          .split('\n')
          .any((l) => RegExp(r'\d{2}:\d{2}:\d{2}\.\d+ \(\+').hasMatch(l)),
      isTrue,
    );
  });
}
